command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="2d38f480998e522e4cfbe2b8a3ca2fef68ff6637"
$target=Join-Path $repo "965093aa9397b0e0419c94270e636d1d427a8948"
Set-Location -LiteralPath $repo
& git fetch origin main --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
$observed=(& git rev-parse refs/remotes/origin/main).Trim()
if($observed -ne $main){throw "main moved before stale-worktree cleanup"}
if(-not (Test-Path -LiteralPath $target -PathType Container)){throw "expected stale worktree path is absent"}
$nestedDirty=@(& git -C $target status --porcelain=v1 -uall)
if($nestedDirty.Count -ne 0){
  $nestedDirty | ForEach-Object { Write-Host ("STALE_WORKTREE_DIRTY="+$_) }
  throw "stale worktree contains changes; refusing removal"
}
$nestedHead=(& git -C $target rev-parse HEAD).Trim()
Write-Host "STALE_WORKTREE_HEAD=$nestedHead"
& git worktree remove $target
if($LASTEXITCODE -ne 0){throw "safe stale worktree removal failed"}
& git worktree prune
if($LASTEXITCODE -ne 0){throw "worktree prune failed"}
if(Test-Path -LiteralPath $target){throw "stale worktree path remains"}
$outerDirty=@(& git status --porcelain=v1 -uall)
if($outerDirty.Count -ne 0){
  $outerDirty | ForEach-Object { Write-Host ("OUTER_WORKTREE_DIRTY="+$_) }
  throw "canonical checkout still dirty after stale-worktree removal"
}
Write-Host "STALE_NESTED_WORKTREE_CLEANUP=PASS"
